/* Leonida Legend — own neon-dusk look, no game artwork, system fonts only. */
:root {
  --bg: #14101d;
  --panel: #1f1830;
  --panel-2: #281d40;
  --ink: #f4eefc;
  --muted: #b9a8d9;
  --accent: #ff5da2;
  --accent-2: #ffb347;
  --line: #3d2f5e;
  --platinum: #a8e6ff;
  --gold: #ffd75e;
  --silver: #d7dde8;
  --bronze: #e09a5f;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: "Segoe UI", system-ui, -apple-system, Arial, sans-serif;
  background: linear-gradient(180deg, #1b1030 0, var(--bg) 260px);
  color: var(--ink);
  line-height: 1.45;
}
.topbar {
  display: flex; flex-wrap: wrap; gap: 20px; justify-content: space-between; align-items: flex-start;
  padding: 22px 28px 10px;
}
.brand h1 { margin: 0; font-size: 34px; letter-spacing: .5px; color: var(--accent-2); }
.tagline { margin: 4px 0 0; color: var(--muted); max-width: 560px; }
.progress-box { min-width: 300px; flex: 0 1 380px; background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 12px 16px; }
.progress-line { display: flex; justify-content: space-between; font-weight: 700; font-size: 17px; }
.progress-track { height: 12px; background: #0d0a16; border-radius: 6px; margin: 8px 0; overflow: hidden; }
#progress-bar { height: 100%; width: 0; background: linear-gradient(90deg, var(--accent), var(--accent-2)); transition: width .3s; }
.grade-counts { display: flex; gap: 12px; flex-wrap: wrap; color: var(--muted); font-size: 13px; }
.grade-counts b { color: var(--ink); }
.view-tabs { display: flex; gap: 8px; padding: 8px 28px 0; }
.tab {
  background: var(--panel); color: var(--muted); border: 1px solid var(--line); border-bottom: none;
  border-radius: 10px 10px 0 0; padding: 9px 18px; font-size: 15px; font-weight: 600; cursor: pointer;
}
.tab.active { background: var(--panel-2); color: var(--ink); }
section { padding: 14px 28px 24px; }
.controls {
  display: flex; flex-wrap: wrap; gap: 12px; align-items: end;
  background: var(--panel-2); border: 1px solid var(--line); border-radius: 0 12px 12px 12px; padding: 14px 16px;
}
.controls label { display: flex; flex-direction: column; gap: 4px; font-size: 12.5px; color: var(--muted); font-weight: 600; }
.controls .search-label { flex: 1 1 220px; }
.controls input[type="search"], .controls select {
  background: #120d20; color: var(--ink); border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; font-size: 14px;
}
.controls .toggle { flex-direction: row; align-items: center; gap: 7px; font-size: 13.5px; color: var(--ink); padding-bottom: 8px; }
.controls button, .import-label {
  background: var(--accent); color: #1c0a16; border: none; border-radius: 8px; padding: 9px 14px;
  font-size: 13.5px; font-weight: 700; cursor: pointer;
}
.import-label { background: var(--panel); color: var(--ink); border: 1px solid var(--line); }
.import-label input { font-size: 11px; max-width: 150px; }
.honesty-note { color: var(--muted); font-size: 13px; max-width: 1000px; }
.result-count { color: var(--accent-2); font-weight: 600; }
.layout { display: grid; grid-template-columns: minmax(0, 1fr) 400px; gap: 18px; align-items: start; }
@media (max-width: 980px) { .layout { grid-template-columns: 1fr; } }
.trophy-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.trophy-row {
  display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; gap: 10px; align-items: start;
  background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; cursor: pointer;
}
.trophy-row:hover, .trophy-row.selected { border-color: var(--accent); }
