.spoiler-hidden .trophy-name, .spoiler-hidden .trophy-desc { filter: blur(5px); user-select: none; }
.detail {
  background: var(--panel); border: 1px solid var(--accent); border-radius: 12px; padding: 16px 18px;
  position: sticky; top: 12px; max-height: calc(100vh - 24px); overflow: auto;
}
.detail h3 { margin: 0 0 4px; font-size: 20px; }
.detail .official { color: var(--muted); font-style: italic; }
.detail h4 { margin: 14px 0 4px; color: var(--accent-2); font-size: 13px; text-transform: uppercase; letter-spacing: .7px; }
